using ahis.template.application.Features.IdentityRoleManagementFeatures;
using ahis.template.application.Shared;
using ahis.template.application.Shared.Mediator;
using ahis.template.domain.Models.ViewModels.IdentityRoleVM;
using FluentResults;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;

namespace ahis.template.api.Controllers.v1;
[ApiController, Route("api/admin/identity/roles")]
public sealed class AdminIdentityRolesController : ControllerBase
{ private readonly IMediator _mediator; public AdminIdentityRolesController(IMediator mediator)=>_mediator=mediator;
 [HttpGet,Authorize(Policy="IdentityRoleReadPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Get(string? name,int pageNumber=1,int pageSize=20){var r=await _mediator.Send(new GetRolesQuery{Name=name,PageNumber=pageNumber,PageSize=pageSize},HttpContext.RequestAborted);return Paged(r);}
 [HttpGet("{roleId}"),Authorize(Policy="IdentityRoleReadPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> GetById(string roleId){var r=await _mediator.Send(new GetRoleQuery{RoleId=roleId},HttpContext.RequestAborted);if(r.IsSuccess)Response.Headers.ETag=r.Value.ETag;return Single(r);}
 [HttpGet("{roleId}/permissions"),Authorize(Policy="IdentityRoleReadPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Permissions(string roleId){var detail=await _mediator.Send(new GetRoleQuery{RoleId=roleId},HttpContext.RequestAborted);if(detail.IsFailed)return Error(detail.Errors);Response.Headers.ETag=detail.Value.ETag;return Single(await _mediator.Send(new GetRolePermissionsQuery{RoleId=roleId},HttpContext.RequestAborted));}
 [HttpPost,Authorize(Policy="IdentityRoleManagementPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Create([FromBody] RoleNameBody body,[FromHeader(Name="X-Step-Up-Proof")]string? proof){var r=await _mediator.Send(new CreateRoleCommand{Name=body?.Name??string.Empty,StepUpProof=proof},HttpContext.RequestAborted);if(r.IsFailed)return Error(r.Errors);Response.Headers.ETag=r.Value.ETag;Response.Headers.CacheControl="no-store";return CreatedAtAction(nameof(GetById),new{roleId=r.Value.Id},new ResponseDto<AdminRoleDetailVM>(r.Value));}
 [HttpPut("{roleId}"),Authorize(Policy="IdentityRoleManagementPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Rename(string roleId,[FromBody] RoleNameBody body,[FromHeader(Name="If-Match")]string? tag,[FromHeader(Name="X-Step-Up-Proof")]string? proof){var r=await _mediator.Send(new RenameRoleCommand{RoleId=roleId,Name=body?.Name??string.Empty,ETag=tag,StepUpProof=proof},HttpContext.RequestAborted);if(r.IsSuccess)Response.Headers.ETag=r.Value.ETag;return Single(r);}
 [HttpDelete("{roleId}"),Authorize(Policy="IdentityRoleManagementPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Delete(string roleId,[FromHeader(Name="X-Step-Up-Proof")]string? proof){var r=await _mediator.Send(new DeleteRoleCommand{RoleId=roleId,StepUpProof=proof},HttpContext.RequestAborted);if(r.IsSuccess){NoStore();return NoContent();}return Error(r);}
 [HttpPut("{roleId}/permissions"),Authorize(Policy="IdentityRoleManagementPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> ReplacePermissions(string roleId,[FromBody] RolePermissionsBody? body,[FromHeader(Name="If-Match")]string? tag,[FromHeader(Name="X-Step-Up-Proof")]string? proof){var r=await _mediator.Send(new ReplaceRolePermissionsCommand{RoleId=roleId,ETag=tag,Permissions=body?.Permissions,StepUpProof=proof},HttpContext.RequestAborted);if(r.IsFailed)return Error(r.Errors);Response.Headers.ETag=r.Value;NoStore();return NoContent();}
 [HttpGet("{roleId}/users"),Authorize(Policy="IdentityRoleReadPolicy"),EnableRateLimiting("AuthenticatedSecurityPolicy")] public async Task<IActionResult> Users(string roleId,int pageNumber=1,int pageSize=20){var r=await _mediator.Send(new GetRoleUsersQuery{RoleId=roleId,PageNumber=pageNumber,PageSize=pageSize},HttpContext.RequestAborted);return Paged(r);}
 private IActionResult Single<T>(Result<T> r){NoStore();return r.IsSuccess?Ok(new ResponseDto<T>(r.Value)):Error(r.Errors);} private IActionResult Paged<T>(Result<PagedResult<List<T>>> r){NoStore();return r.IsSuccess?Ok(new PagedResponseDto<List<T>>(r.Value.Data,r.Value.TotalCount,r.Value.PageNumber,r.Value.PageSize)):Error(r.Errors);} private IActionResult Error(Result r)=>Error(r.Errors); private IActionResult Error(IEnumerable<IError> errors){NoStore();var e=errors.First();if(e.Metadata.ContainsKey("PreconditionRequired"))return Problem(statusCode:428);if(e.Metadata.ContainsKey("PreconditionFailed"))return Problem(statusCode:412);if(e.Metadata.ContainsKey("NotFound"))return Problem(statusCode:404);if(e.Metadata.ContainsKey("Conflict"))return Problem(statusCode:409);if(e.Metadata.ContainsKey("Validation"))return ValidationProblem(statusCode:400);return Problem(statusCode:500);} private void NoStore()=>Response.Headers.CacheControl="no-store";
 public sealed class RoleNameBody { public string? Name {get;init;} }
 public sealed class RolePermissionsBody { public IReadOnlyCollection<string>? Permissions {get;init;} }
}
